/bin/bash -lc 'set -e
H="$HORIZON_GIT"; BASE=d80ceb90affb7427f7fa4607fcce5f7558ddd961; SNAP=$("$H" rev-parse HEAD); echo SNAP=$SNAP; T=$(mktemp -d); "$H" archive --format=tar "$BASE" -- MainProjects/Algebraic-Jacobian-Challenge/AlgebraicJacobian > "$T/base.tar"; "$H" archive --format=tar "$SNAP" -- MainProjects/Algebraic-Jacobian-Challenge/AlgebraicJacobian > "$T/head.tar"; mkdir "$T/base" "$T/head"; tar -xf "$T/base.tar" -C "$T/base"; tar -xf "$T/head.tar" -C "$T/head"; python3 - "$T" <<'"'PY'
import sys,pathlib
from archon_horizon.search.index import extract_declarations
T=pathlib.Path(sys.argv[1]); sub='MainProjects/Algebraic-Jacobian-Challenge/AlgebraicJacobian'
def split_top(s):
 d=0;q=False;e=False
 for i,c in enumerate(s):
  if q:
   if e:e=False
   elif c=='\\\\':e=True
   elif c=='\"':q=False
   continue
  if c=='\"':q=True;continue
  if c in '([{':d+=1
  elif c in ')]}':d=max(0,d-1)
  elif c==':' and d==0 and not (i+1<len(s) and s[i+1]=='='):return s[:i],s[i+1:]
 return s,''
for tag in ('base','head'):
 root=T/tag/sub;fs=list(root.rglob('*.lean'));raw='';ds=[]
 for p in fs:
  t=p.read_text(errors='replace');raw+=t;ds+=extract_declarations(t,library='AJC',file=str(p.relative_to(root)))
 po=pd=res=di=0;names=[]
 for x in ds:
  pre,out=split_top(x.signature);n=pre.count('.RepresentableBy');po+=n;pd+=bool(n)
  if '.RepresentableBy' in out:
   res+=1
   if not n:di+=1;names.append(x.name)
 print(tag,'files',len(fs),'decls',len(ds),'strict',raw.count('(rep :'),'prefix_occ',po,'prefix_decls',pd,'result',res,'direct',di)
 if tag=='head':
  print('DIRECT_ADDITIONS_FROM_BASE_EXPECTED',sorted(set(names)))
PY
HEAD1="'$("$HORIZON_GIT" rev-parse HEAD); echo HEAD_CHECK=$SNAP/$HEAD1; rm -rf "$T"'

